BEGIN;

INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class)
VALUES('WBS.H1.ACCOUNTING.RECONCILE','WBS','HIGH','RECONCILER')
ON CONFLICT(permission_code) DO UPDATE SET active=true,version=permission_catalog.version+1,effective_to=NULL;

CREATE TABLE wbs_h1_accounting_control_reconciliation(
  reconciliation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL,entity_id uuid NOT NULL,control_run_id uuid NOT NULL,
  control_receipt_id uuid NOT NULL,control_receipt_hash text NOT NULL CHECK(control_receipt_hash~'^sha256:[0-9a-f]{64}$'),
  company_code text NOT NULL,currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),module_code text NOT NULL CHECK(module_code='PAYABLE'),
  settings_bundle_hash text NOT NULL CHECK(settings_bundle_hash~'^sha256:[0-9a-f]{64}$'),
  admission_proofs jsonb NOT NULL CHECK(jsonb_typeof(admission_proofs)='array' AND jsonb_array_length(admission_proofs)>0),
  source_population_hash text NOT NULL CHECK(source_population_hash~'^sha256:[0-9a-f]{64}$'),
  expected_row_count integer NOT NULL CHECK(expected_row_count>0),actual_source_count integer NOT NULL CHECK(actual_source_count>0),
  expected_debit numeric(24,4) NOT NULL,expected_credit numeric(24,4) NOT NULL,
  actual_debit numeric(24,4) NOT NULL,actual_credit numeric(24,4) NOT NULL,
  expected_hash text NOT NULL CHECK(expected_hash~'^sha256:[0-9a-f]{64}$'),
  actual_hash text NOT NULL CHECK(actual_hash~'^sha256:[0-9a-f]{64}$'),
  status text NOT NULL CHECK(status IN('MATCHED','MISMATCH')),
  receipt_document jsonb NOT NULL,receipt_hash text NOT NULL CHECK(receipt_hash=refs_jsonb_hash(receipt_document)),
  request_hash text NOT NULL CHECK(request_hash~'^sha256:[0-9a-f]{64}$'),idempotency_key text NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 200),
  retained_by text NOT NULL,retained_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(tenant_id,entity_id,idempotency_key),UNIQUE(tenant_id,entity_id,control_run_id,module_code,control_receipt_hash,settings_bundle_hash),
  FOREIGN KEY(tenant_id,entity_id) REFERENCES entity(tenant_id,entity_id),
  FOREIGN KEY(control_receipt_id) REFERENCES wbs_h1_accounting_population_receipt(receipt_id),
  FOREIGN KEY(control_run_id) REFERENCES wbs_h1_accounting_population_run(run_id)
);

CREATE TABLE wbs_h1_accounting_control_reconciliation_account(
  reconciliation_id uuid NOT NULL REFERENCES wbs_h1_accounting_control_reconciliation(reconciliation_id),
  tenant_id uuid NOT NULL,entity_id uuid NOT NULL,period_id uuid NOT NULL,period_code text NOT NULL CHECK(period_code~'^2026-0[1-6]$'),
  currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),module_code text NOT NULL CHECK(module_code='PAYABLE'),account_code text NOT NULL,
  expected_line_count integer NOT NULL CHECK(expected_line_count>=0),actual_line_count integer NOT NULL CHECK(actual_line_count>=0),
  expected_debit numeric(24,4) NOT NULL,expected_credit numeric(24,4) NOT NULL,actual_debit numeric(24,4) NOT NULL,actual_credit numeric(24,4) NOT NULL,
  expected_hash text,actual_hash text,status text NOT NULL CHECK(status IN('MATCHED','MISMATCH')),
  row_document jsonb NOT NULL,row_hash text NOT NULL CHECK(row_hash=refs_jsonb_hash(row_document)),
  PRIMARY KEY(reconciliation_id,period_id,currency,module_code,account_code),
  FOREIGN KEY(tenant_id,entity_id,period_id) REFERENCES accounting_period(tenant_id,entity_id,period_id)
);

ALTER TABLE wbs_h1_accounting_control_reconciliation ENABLE ROW LEVEL SECURITY;
ALTER TABLE wbs_h1_accounting_control_reconciliation_account ENABLE ROW LEVEL SECURITY;
CREATE POLICY wbs_h1_accounting_control_reconciliation_scope ON wbs_h1_accounting_control_reconciliation USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id)) WITH CHECK(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE POLICY wbs_h1_accounting_control_reconciliation_account_scope ON wbs_h1_accounting_control_reconciliation_account USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id)) WITH CHECK(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE TRIGGER wbs_h1_accounting_control_reconciliation_append_only BEFORE UPDATE OR DELETE ON wbs_h1_accounting_control_reconciliation FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER wbs_h1_accounting_control_reconciliation_account_append_only BEFORE UPDATE OR DELETE ON wbs_h1_accounting_control_reconciliation_account FOR EACH ROW EXECUTE FUNCTION reject_mutation();
REVOKE ALL ON wbs_h1_accounting_control_reconciliation,wbs_h1_accounting_control_reconciliation_account FROM PUBLIC,refs_app;
GRANT SELECT ON wbs_h1_accounting_control_reconciliation,wbs_h1_accounting_control_reconciliation_account TO refs_app;

CREATE FUNCTION refs_retain_wbs_h1_accounting_control_reconciliation(
  p_tenant uuid,p_entity uuid,p_control_run uuid,p_expected_control_receipt_hash text,p_expected_settings_bundle_hash text,
  p_idempotency_key text,p_request_hash text,p_reason text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor(); control_run wbs_h1_accounting_population_run;control_receipt wbs_h1_accounting_population_receipt;
 stored wbs_h1_accounting_control_reconciliation;settings_bundle jsonb;settings_hash text;expected_request text;new_id uuid:=gen_random_uuid();
 expected_count integer;source_count integer;expected_debit numeric;expected_credit numeric;actual_debit numeric;actual_credit numeric;
 expected_hash text;actual_hash text;source_population_hash text;admission_proofs jsonb;result_status text;doc jsonb;payload jsonb;
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_entity,'WBS.H1.ACCOUNTING.RECONCILE');
 IF actor IS NULL OR p_control_run IS NULL OR p_expected_control_receipt_hash!~'^sha256:[0-9a-f]{64}$' OR p_expected_settings_bundle_hash!~'^sha256:[0-9a-f]{64}$' OR p_request_hash!~'^sha256:[0-9a-f]{64}$' OR length(p_idempotency_key) NOT BETWEEN 8 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 8 AND 2000 THEN RAISE EXCEPTION 'WBS accounting reconciliation input is invalid' USING ERRCODE='22023';END IF;
 expected_request:=refs_jsonb_hash(jsonb_build_object('tenant_id',p_tenant,'entity_id',p_entity,'control_run_id',p_control_run,'expected_control_receipt_hash',p_expected_control_receipt_hash,'expected_settings_bundle_hash',p_expected_settings_bundle_hash,'module_code','PAYABLE','reason',btrim(p_reason)));
 IF p_request_hash<>expected_request THEN RAISE EXCEPTION 'WBS accounting reconciliation request hash drifted' USING ERRCODE='23514';END IF;
 SELECT * INTO stored FROM wbs_h1_accounting_control_reconciliation WHERE tenant_id=p_tenant AND entity_id=p_entity AND idempotency_key=p_idempotency_key FOR SHARE;
 IF FOUND THEN IF stored.request_hash<>p_request_hash OR stored.retained_by<>actor THEN RAISE EXCEPTION 'WBS accounting reconciliation idempotency conflict' USING ERRCODE='23505';END IF;RETURN stored.receipt_document||jsonb_build_object('reconciliation_id',stored.reconciliation_id,'receipt_hash',stored.receipt_hash,'idempotent',true);END IF;
 -- Freeze every mutable relation contributing to the claimed complete
 -- provider-to-ledger population. Row locks alone cannot prevent a concurrent
 -- Final1 admission from inserting a new retained source or superseding a raw
 -- event between READ COMMITTED statements.
 LOCK TABLE wbs_final1_retained_evidence_admission,wbs_final1_signed_control_total,wbs_final1_retained_source_row,raw_event,source_document,source_document_line,source_link,attachment,journal_entry,journal_line,ledger_line IN SHARE MODE;
 SELECT * INTO control_run FROM wbs_h1_accounting_population_run WHERE run_id=p_control_run AND tenant_id=p_tenant AND entity_id=p_entity FOR SHARE;
 SELECT * INTO control_receipt FROM wbs_h1_accounting_population_receipt WHERE run_id=p_control_run AND tenant_id=p_tenant AND entity_id=p_entity FOR SHARE;
 IF control_run.run_id IS NULL OR control_receipt.receipt_id IS NULL OR control_receipt.receipt_hash<>p_expected_control_receipt_hash OR control_receipt.receipt_document->>'accounting_authority'<>'CONTROL_EVIDENCE_ONLY' OR control_receipt.receipt_document#>>'{can_create_draft}'<>'false' OR control_receipt.receipt_document#>>'{can_review}'<>'false' OR control_receipt.receipt_document#>>'{can_approve}'<>'false' OR control_receipt.receipt_document#>>'{can_post}'<>'false' THEN RAISE EXCEPTION 'Finalized WBS accounting control receipt is missing or drifted' USING ERRCODE='40001';END IF;
 SELECT jsonb_agg(refs_read_wbs_ai_approved_entity_period_settings(p_tenant,p_entity,ap.period_id) ORDER BY ap.period_code) INTO settings_bundle FROM accounting_period ap WHERE ap.tenant_id=p_tenant AND ap.entity_id=p_entity AND ap.ledger_code='PRIMARY' AND ap.period_code~'^2026-0[1-6]$' AND ap.starts_on=(ap.period_code||'-01')::date AND ap.ends_on=(ap.starts_on+interval '1 month'-interval '1 day')::date;
 IF jsonb_array_length(COALESCE(settings_bundle,'[]'::jsonb))<>6 THEN RAISE EXCEPTION 'Complete approved H1 Settings are required' USING ERRCODE='23503';END IF;
 settings_hash:=refs_jsonb_hash(settings_bundle);IF settings_hash<>p_expected_settings_bundle_hash THEN RAISE EXCEPTION 'Approved Settings CAS drifted' USING ERRCODE='40001';END IF;

 -- Lock the authoritative source parents before inspecting child evidence.
 -- The parent UPDATE lock conflicts with FK key-share acquisition for a new
 -- source link; the child locks prevent status/hash/link mutation while this
 -- receipt and its audit/outbox evidence are committed.
 PERFORM d.source_document_id FROM source_document d
 JOIN wbs_final1_retained_source_row r ON r.tenant_id=d.tenant_id AND r.entity_id=d.entity_id AND r.source_document_id=d.source_document_id
 JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id
 WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND a.company_code=control_run.company_code
   AND r.accounting_period_id IN(SELECT period_id FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND ledger_code='PRIMARY' AND period_code~'^2026-0[1-6]$')
 ORDER BY d.source_document_id FOR UPDATE OF d;
 PERFORM l.source_document_line_id FROM source_document_line l
 JOIN wbs_final1_retained_source_row r ON r.tenant_id=l.tenant_id AND r.entity_id=l.entity_id AND r.source_document_id=l.source_document_id AND r.source_document_line_id=l.source_document_line_id
 JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id
 WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND a.company_code=control_run.company_code
 ORDER BY l.source_document_line_id FOR SHARE OF l;
 PERFORM sl.source_link_id FROM source_link sl
 JOIN wbs_final1_retained_source_row r ON r.tenant_id=sl.tenant_id AND r.entity_id=sl.entity_id AND r.source_document_id=sl.source_document_id
 JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id
 WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND a.company_code=control_run.company_code
 ORDER BY sl.source_link_id FOR SHARE OF sl;
 PERFORM att.attachment_id FROM attachment att JOIN source_link sl ON sl.tenant_id=att.tenant_id AND sl.entity_id=att.entity_id AND sl.attachment_id=att.attachment_id AND sl.link_type='SOURCE_ATTACHMENT'
 JOIN wbs_final1_retained_source_row r ON r.tenant_id=sl.tenant_id AND r.entity_id=sl.entity_id AND r.source_document_id=sl.source_document_id
 JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id
 WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND a.company_code=control_run.company_code
 ORDER BY att.attachment_id FOR SHARE OF att;
 PERFORM je.journal_entry_id FROM journal_entry je JOIN source_link sl ON sl.tenant_id=je.tenant_id AND sl.entity_id=je.entity_id AND sl.journal_entry_id=je.journal_entry_id AND sl.link_type='SOURCE_TO_JE'
 JOIN wbs_final1_retained_source_row r ON r.tenant_id=sl.tenant_id AND r.entity_id=sl.entity_id AND r.source_document_id=sl.source_document_id
 JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id
 WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND a.company_code=control_run.company_code
 ORDER BY je.journal_entry_id FOR SHARE OF je;

 CREATE TEMP TABLE _wbs273_expected ON COMMIT DROP AS
 SELECT l.period_id,l.period_code,l.currency,l.account_code,count(*)::integer line_count,sum(l.debit_amount)::numeric(24,4) debit,sum(l.credit_amount)::numeric(24,4) credit,
  'sha256:'||encode(digest(convert_to(string_agg(l.line_hash||E'\n','' ORDER BY l.row_ordinal),'UTF8'),'sha256'),'hex') row_hash
 FROM wbs_h1_accounting_evidence_line l JOIN accounting_period ap ON ap.tenant_id=l.tenant_id AND ap.entity_id=l.entity_id AND ap.period_id=l.period_id AND ap.ledger_code='PRIMARY' AND ap.period_code=l.period_code AND ap.starts_on=(ap.period_code||'-01')::date AND ap.ends_on=(ap.starts_on+interval '1 month'-interval '1 day')::date WHERE l.run_id=p_control_run AND NOT l.excluded_from_h1 AND l.come_from='PAYABLE'
 GROUP BY l.period_id,l.period_code,l.currency,l.account_code;
 IF NOT EXISTS(SELECT 1 FROM _wbs273_expected) OR EXISTS(SELECT 1 FROM wbs_h1_accounting_evidence_line l WHERE l.run_id=p_control_run AND NOT l.excluded_from_h1 AND l.come_from='PAYABLE' AND (l.completeness_status<>'COMPLETE' OR l.account_code IS NULL OR l.business_guid IS NULL)) OR (SELECT sum(line_count) FROM _wbs273_expected)<>(SELECT sum(row_count) FROM wbs_h1_accounting_module_receipt WHERE run_id=p_control_run AND module_code='PAYABLE') THEN RAISE EXCEPTION 'WBS PAYABLE control population is incomplete or ambiguous' USING ERRCODE='23514';END IF;
 IF (SELECT count(DISTINCT period_id) FROM _wbs273_expected)<>6 OR (SELECT count(*) FROM wbs_h1_accounting_module_receipt m JOIN accounting_period ap ON ap.tenant_id=m.tenant_id AND ap.entity_id=m.entity_id AND ap.period_id=m.period_id AND ap.ledger_code='PRIMARY' AND ap.period_code=m.period_code WHERE m.run_id=p_control_run AND m.module_code='PAYABLE')<>6 THEN RAISE EXCEPTION 'WBS PAYABLE control must cover all six exact PRIMARY H1 periods' USING ERRCODE='23514';END IF;

 CREATE TEMP TABLE _wbs273_source ON COMMIT DROP AS
 SELECT r.source_document_id,r.source_document_line_id,r.accounting_period_id period_id,ap.period_code,l.external_dimension_refs->>'signed_business_id' business_guid,r.raw_row_hash,
   r.wbs_final1_retained_evidence_admission_id admission_id,a.snapshot_id,a.request_hash admission_request_hash,a.package_hash,a.package_raw_hash,ct.control_totals_hash,
   d.payload_hash,d.gross_amount,l.amount,re.source_record_id,re.source_version,d.business_date,d.accounting_date,l.external_dimension_refs->>'signed_invoice_date' signed_invoice_date,l.external_dimension_refs->>'signed_charge_code' signed_charge_code,attachments.attachment_set_hash,
   refs_jsonb_hash(jsonb_build_object('source_document_id',r.source_document_id,'source_document_line_id',r.source_document_line_id,'source_payload_hash',d.payload_hash,'raw_row_hash',r.raw_row_hash,'source_record_id',re.source_record_id,'source_version',re.source_version,'admission_id',r.wbs_final1_retained_evidence_admission_id,'snapshot_id',a.snapshot_id,'package_hash',a.package_hash,'package_raw_hash',a.package_raw_hash,'control_totals_hash',ct.control_totals_hash,'period_id',r.accounting_period_id,'period_code',ap.period_code,'business_date',d.business_date,'accounting_date',d.accounting_date,'signed_invoice_date',l.external_dimension_refs->>'signed_invoice_date','signed_charge_code',l.external_dimension_refs->>'signed_charge_code','currency',d.currency,'amount',to_char(l.amount,'FM999999999999999999990.0000'),'business_guid',l.external_dimension_refs->>'signed_business_id','attachment_set_hash',attachments.attachment_set_hash)) source_hash
 FROM wbs_final1_retained_source_row r JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id AND a.tenant_id=r.tenant_id AND a.entity_id=r.entity_id AND a.domain=r.domain AND a.algorithm='Ed25519'
 JOIN wbs_final1_signed_control_total ct ON ct.tenant_id=a.tenant_id AND ct.entity_id=a.entity_id AND ct.wbs_final1_retained_evidence_admission_id=a.wbs_final1_retained_evidence_admission_id AND ct.domain='PAYABLES'
 JOIN raw_event re ON re.tenant_id=r.tenant_id AND re.entity_id=r.entity_id AND re.raw_event_id=r.raw_event_id AND re.source_system='WBS' AND re.source_module='payable' AND re.source_entity_id=a.company_code AND re.source_record_id=r.source_record_id AND re.source_version=r.source_version AND re.is_current
 JOIN source_document d ON d.tenant_id=r.tenant_id AND d.entity_id=r.entity_id AND d.source_document_id=r.source_document_id AND d.raw_event_id=re.raw_event_id AND d.source_system='WBS' AND d.source_module='payable' AND d.source_entity_id=a.company_code AND d.source_record_id=r.source_record_id AND d.source_version=r.source_version AND d.document_type='WBS_FINAL1_PAYABLE' AND d.payload_hash=r.raw_row_hash
  JOIN source_document_line l ON l.tenant_id=r.tenant_id AND l.entity_id=r.entity_id AND l.source_document_id=r.source_document_id AND l.source_document_line_id=r.source_document_line_id AND l.amount=d.gross_amount
  JOIN LATERAL (SELECT count(*)::integer attachment_count,bool_and(att.scan_status='CLEAN' AND att.finalization_status='VERIFIED_CLEAN') all_clean,refs_jsonb_hash(jsonb_agg(jsonb_build_object('attachment_id',att.attachment_id,'content_hash',att.content_hash,'storage_version',att.storage_version,'scan_status',att.scan_status,'finalization_status',att.finalization_status) ORDER BY att.attachment_id)) attachment_set_hash FROM source_link asl JOIN attachment att ON att.tenant_id=asl.tenant_id AND att.entity_id=asl.entity_id AND att.attachment_id=asl.attachment_id WHERE asl.tenant_id=r.tenant_id AND asl.entity_id=r.entity_id AND asl.source_document_id=r.source_document_id AND asl.link_type='SOURCE_ATTACHMENT') attachments ON attachments.attachment_count>=1 AND attachments.all_clean
 JOIN accounting_period ap ON ap.tenant_id=r.tenant_id AND ap.entity_id=r.entity_id AND ap.period_id=r.accounting_period_id AND ap.ledger_code='PRIMARY' AND ap.period_code~'^2026-0[1-6]$' AND ap.starts_on=(ap.period_code||'-01')::date AND ap.ends_on=(ap.starts_on+interval '1 month'-interval '1 day')::date AND d.accounting_date BETWEEN ap.starts_on AND ap.ends_on
 WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND a.company_code=control_run.company_code AND d.currency=control_run.currency
  AND a.row_count=(ct.control_totals->>'row_count')::integer AND a.row_count=(SELECT count(*) FROM wbs_final1_retained_source_row ar WHERE ar.tenant_id=a.tenant_id AND ar.entity_id=a.entity_id AND ar.wbs_final1_retained_evidence_admission_id=a.wbs_final1_retained_evidence_admission_id)
  AND l.external_dimension_refs->>'schema_version'='WBS_FINAL1_RETAINED_SOURCE_LINE_V1' AND l.external_dimension_refs->>'domain'='PAYABLES' AND l.external_dimension_refs->>'snapshot_id'=a.snapshot_id::text AND l.external_dimension_refs->>'package_hash'=a.package_hash AND l.external_dimension_refs->>'raw_row_hash'=r.raw_row_hash AND l.external_dimension_refs->>'accounting_period_id'=r.accounting_period_id::text AND l.external_dimension_refs->>'accounting_period_resolution'='EXACT_PRIMARY_PERIOD' AND l.external_dimension_refs ?& ARRAY['source_surface','signed_invoice_no','signed_invoice_date','signed_business_id','signed_charge_code'] AND l.external_dimension_refs->'source_surface'=jsonb_build_object('database','wbsdata','table','account_book_payable_info') AND d.document_no IS NOT DISTINCT FROM NULLIF(l.external_dimension_refs->>'signed_invoice_no','') AND l.external_dimension_refs->>'signed_invoice_date'=d.business_date::text AND d.business_date=d.accounting_date;
 IF (SELECT count(*) FROM _wbs273_source)<>(SELECT count(*) FROM wbs_final1_retained_source_row r JOIN raw_event re ON re.tenant_id=r.tenant_id AND re.entity_id=r.entity_id AND re.raw_event_id=r.raw_event_id AND re.source_record_id=r.source_record_id AND re.source_version=r.source_version AND re.is_current JOIN wbs_final1_retained_evidence_admission a ON a.tenant_id=r.tenant_id AND a.entity_id=r.entity_id AND a.wbs_final1_retained_evidence_admission_id=r.wbs_final1_retained_evidence_admission_id AND a.domain='PAYABLES' AND a.company_code=control_run.company_code WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND r.accounting_period_id IN(SELECT period_id FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND ledger_code='PRIMARY' AND period_code~'^2026-0[1-6]$')) THEN RAISE EXCEPTION 'Provider-signed PAYABLE source population contains identity drift or unproven rows' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM _wbs273_source s JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=s.admission_id WHERE a.date_from<control_run.date_from OR a.date_to>control_run.date_to OR a.date_from>a.date_to) THEN RAISE EXCEPTION 'Provider admission scope crosses the exact H1 control period' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM _wbs273_source s JOIN wbs_final1_retained_evidence_admission a ON a.wbs_final1_retained_evidence_admission_id=s.admission_id JOIN wbs_final1_signed_control_total c ON c.tenant_id=a.tenant_id AND c.entity_id=a.entity_id AND c.wbs_final1_retained_evidence_admission_id=a.wbs_final1_retained_evidence_admission_id GROUP BY s.admission_id,a.row_count,c.control_totals HAVING count(*)<>a.row_count OR c.control_totals IS DISTINCT FROM jsonb_build_object('row_count',a.row_count,'currency_totals',jsonb_build_array(jsonb_build_object('currency',control_run.currency,'row_count',a.row_count,'amount_total',to_char(sum(s.amount),'FM999999999999999999990.0000'))))) THEN RAISE EXCEPTION 'Provider admission row count or signed control total differs from the exact retained source population' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM _wbs273_source WHERE business_guid IS NULL GROUP BY source_document_id HAVING true) OR EXISTS(SELECT business_guid FROM _wbs273_source GROUP BY business_guid HAVING count(*)<>1) OR EXISTS(SELECT business_guid FROM wbs_h1_accounting_evidence_line WHERE run_id=p_control_run AND NOT excluded_from_h1 AND come_from='PAYABLE' GROUP BY business_guid HAVING (SELECT count(*) FROM _wbs273_source s WHERE s.business_guid=wbs_h1_accounting_evidence_line.business_guid)<>1) OR EXISTS(SELECT 1 FROM _wbs273_source s WHERE NOT EXISTS(SELECT 1 FROM wbs_h1_accounting_evidence_line l WHERE l.run_id=p_control_run AND NOT l.excluded_from_h1 AND l.come_from='PAYABLE' AND l.business_guid=s.business_guid)) THEN RAISE EXCEPTION 'Provider-signed Final1 PAYABLES population is missing, ambiguous, or not complete against control' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM _wbs273_source s JOIN LATERAL (SELECT sum(l.debit_amount)::numeric(24,4) debit,sum(l.credit_amount)::numeric(24,4) credit,(array_agg(l.period_id ORDER BY l.period_id))[1] period_id,count(DISTINCT l.period_id) period_count FROM wbs_h1_accounting_evidence_line l WHERE l.run_id=p_control_run AND NOT l.excluded_from_h1 AND l.come_from='PAYABLE' AND l.business_guid=s.business_guid) c ON true WHERE c.period_count<>1 OR c.period_id<>s.period_id OR c.debit<>s.gross_amount OR c.credit<>s.gross_amount OR s.gross_amount<>s.amount) THEN RAISE EXCEPTION 'Provider-signed PAYABLE amount or period differs from the exact business control' USING ERRCODE='23514';END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('admission_id',a.wbs_final1_retained_evidence_admission_id,'snapshot_id',a.snapshot_id,'request_hash',a.request_hash,'package_hash',a.package_hash,'package_raw_hash',a.package_raw_hash,'control_totals_hash',c.control_totals_hash,'row_count',a.row_count) ORDER BY a.wbs_final1_retained_evidence_admission_id),'[]'::jsonb) INTO admission_proofs FROM wbs_final1_retained_evidence_admission a JOIN wbs_final1_signed_control_total c ON c.tenant_id=a.tenant_id AND c.entity_id=a.entity_id AND c.wbs_final1_retained_evidence_admission_id=a.wbs_final1_retained_evidence_admission_id AND c.domain='PAYABLES' WHERE a.tenant_id=p_tenant AND a.entity_id=p_entity AND a.domain='PAYABLES' AND a.algorithm='Ed25519' AND EXISTS(SELECT 1 FROM _wbs273_source s WHERE s.admission_id=a.wbs_final1_retained_evidence_admission_id);
 IF jsonb_array_length(admission_proofs)<>(SELECT count(DISTINCT admission_id) FROM _wbs273_source) THEN RAISE EXCEPTION 'Provider admission proofs are incomplete or ambiguous' USING ERRCODE='23514';END IF;
 SELECT 'sha256:'||encode(digest(convert_to(string_agg(source_hash||E'\n','' ORDER BY period_code,source_document_id,source_document_line_id),'UTF8'),'sha256'),'hex') INTO source_population_hash FROM _wbs273_source;
 CREATE TEMP TABLE _wbs273_actual ON COMMIT DROP AS
 SELECT ll.period_id,ap.period_code,ll.currency,ll.account_code,count(*)::integer line_count,sum(ll.debit_amount)::numeric(24,4) debit,sum(ll.credit_amount)::numeric(24,4) credit,
  'sha256:'||encode(digest(convert_to(string_agg(refs_jsonb_hash(jsonb_build_object('ledger_line_id',ll.ledger_line_id,'journal_entry_id',ll.journal_entry_id,'journal_line_id',ll.journal_line_id,'account_code',ll.account_code,'debit_amount',to_char(ll.debit_amount,'FM999999999999999999990.0000'),'credit_amount',to_char(ll.credit_amount,'FM999999999999999999990.0000'),'currency',ll.currency))||E'\n','' ORDER BY ll.ledger_line_id),'UTF8'),'sha256'),'hex') row_hash
 FROM _wbs273_source s JOIN source_link src ON src.tenant_id=p_tenant AND src.entity_id=p_entity AND src.source_document_id=s.source_document_id AND src.link_type='SOURCE_TO_JE'
 JOIN journal_entry je ON je.tenant_id=p_tenant AND je.entity_id=p_entity AND je.journal_entry_id=src.journal_entry_id AND je.status='POSTED'
 JOIN ledger_line ll ON ll.tenant_id=p_tenant AND ll.entity_id=p_entity AND ll.journal_entry_id=je.journal_entry_id
 JOIN journal_line jl ON jl.tenant_id=ll.tenant_id AND jl.entity_id=ll.entity_id AND jl.journal_line_id=ll.journal_line_id AND jl.period_id=ll.period_id AND jl.account_code=ll.account_code AND jl.debit_amount=ll.debit_amount AND jl.credit_amount=ll.credit_amount AND jl.member_ref IS NOT DISTINCT FROM ll.member_ref AND jl.dimensions=ll.dimensions
 JOIN accounting_period ap ON ap.tenant_id=ll.tenant_id AND ap.entity_id=ll.entity_id AND ap.period_id=ll.period_id
 WHERE ll.currency=control_run.currency AND EXISTS(SELECT 1 FROM source_link x WHERE x.tenant_id=ll.tenant_id AND x.entity_id=ll.entity_id AND x.link_type='JE_LINE_TO_LEDGER' AND x.journal_entry_id=ll.journal_entry_id AND x.journal_line_id=ll.journal_line_id AND x.posting_batch_id=ll.posting_batch_id AND x.ledger_line_id=ll.ledger_line_id)
 GROUP BY ll.period_id,ap.period_code,ll.currency,ll.account_code;
 IF EXISTS(SELECT s.source_document_id FROM _wbs273_source s LEFT JOIN source_link x ON x.tenant_id=p_tenant AND x.entity_id=p_entity AND x.source_document_id=s.source_document_id AND x.link_type='SOURCE_TO_JE' LEFT JOIN journal_entry j ON j.tenant_id=p_tenant AND j.entity_id=p_entity AND j.journal_entry_id=x.journal_entry_id GROUP BY s.source_document_id HAVING count(x.journal_entry_id)<>1 OR count(j.journal_entry_id) FILTER(WHERE j.status='POSTED')<>1) THEN RAISE EXCEPTION 'Formal PAYABLES source must have exactly one accounting link and it must be the unique Posted journal' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT x.journal_entry_id FROM source_link x JOIN _wbs273_source s ON s.source_document_id=x.source_document_id WHERE x.tenant_id=p_tenant AND x.entity_id=p_entity AND x.link_type='SOURCE_TO_JE' GROUP BY x.journal_entry_id HAVING count(DISTINCT x.source_document_id)<>1) THEN RAISE EXCEPTION 'Formal PAYABLES source-to-Journal lineage is not one-to-one' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM _wbs273_actual) THEN RAISE EXCEPTION 'Formal PAYABLES ledger population is missing' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT account_code,period_id FROM (SELECT account_code,period_id FROM _wbs273_expected UNION SELECT account_code,period_id FROM _wbs273_actual) a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(settings_bundle) s JOIN LATERAL jsonb_array_elements(s#>'{coa,settings,accounts}') c ON true JOIN LATERAL jsonb_array_elements(s#>'{report_mapping,settings,account_mappings}') m ON m->>'account_code'=c->>'account_code' AND m->>'account_role'=c->>'role' WHERE (s->>'period_id')::uuid=a.period_id AND c->>'account_code'=a.account_code AND c->>'status'='ACTIVE' AND c->>'posting_allowed'='true')) THEN RAISE EXCEPTION 'Approved Settings/Mapping do not exactly cover reconciliation accounts' USING ERRCODE='23514';END IF;

 SELECT sum(line_count),sum(debit),sum(credit),'sha256:'||encode(digest(convert_to(string_agg(row_hash||E'\n','' ORDER BY period_code,currency,account_code),'UTF8'),'sha256'),'hex') INTO expected_count,expected_debit,expected_credit,expected_hash FROM _wbs273_expected;
 SELECT count(*),sum(debit),sum(credit),'sha256:'||encode(digest(convert_to(string_agg(row_hash||E'\n','' ORDER BY period_code,currency,account_code),'UTF8'),'sha256'),'hex') INTO source_count,actual_debit,actual_credit,actual_hash FROM _wbs273_actual;
 result_status:=CASE WHEN NOT EXISTS(SELECT 1 FROM _wbs273_expected e FULL JOIN _wbs273_actual a USING(period_id,period_code,currency,account_code) WHERE e.line_count IS DISTINCT FROM a.line_count OR e.debit IS DISTINCT FROM a.debit OR e.credit IS DISTINCT FROM a.credit) THEN 'MATCHED' ELSE 'MISMATCH' END;
 doc:=jsonb_build_object('schema_version','WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION_RECEIPT_V1','control_run_id',p_control_run,'control_receipt_id',control_receipt.receipt_id,'control_receipt_hash',control_receipt.receipt_hash,'control_accounting_authority','CONTROL_EVIDENCE_ONLY','accounting_authority','RECONCILIATION_EVIDENCE_ONLY','company_code',control_run.company_code,'date_from','2026-01-01','date_to','2026-06-30','currency',control_run.currency,'module_code','PAYABLE','settings_bundle_hash',settings_hash,'admission_proofs',admission_proofs,'source_population_hash',source_population_hash,'expected_row_count',expected_count,'actual_source_count',(SELECT count(*) FROM _wbs273_source),'expected_debit_amount',to_char(expected_debit,'FM999999999999999999990.0000'),'expected_credit_amount',to_char(expected_credit,'FM999999999999999999990.0000'),'actual_debit_amount',to_char(actual_debit,'FM999999999999999999990.0000'),'actual_credit_amount',to_char(actual_credit,'FM999999999999999999990.0000'),'expected_hash',expected_hash,'actual_hash',actual_hash,'status',result_status,'population_complete',true,'can_create_draft',false,'can_review',false,'can_approve',false,'can_post',false);
 INSERT INTO wbs_h1_accounting_control_reconciliation(reconciliation_id,tenant_id,entity_id,control_run_id,control_receipt_id,control_receipt_hash,company_code,currency,module_code,settings_bundle_hash,admission_proofs,source_population_hash,expected_row_count,actual_source_count,expected_debit,expected_credit,actual_debit,actual_credit,expected_hash,actual_hash,status,receipt_document,receipt_hash,request_hash,idempotency_key,retained_by) VALUES(new_id,p_tenant,p_entity,p_control_run,control_receipt.receipt_id,control_receipt.receipt_hash,control_run.company_code,control_run.currency,'PAYABLE',settings_hash,admission_proofs,source_population_hash,expected_count,(SELECT count(*) FROM _wbs273_source),expected_debit,expected_credit,COALESCE(actual_debit,0),COALESCE(actual_credit,0),expected_hash,actual_hash,result_status,doc,refs_jsonb_hash(doc),p_request_hash,p_idempotency_key,actor) RETURNING * INTO stored;
 INSERT INTO wbs_h1_accounting_control_reconciliation_account(reconciliation_id,tenant_id,entity_id,period_id,period_code,currency,module_code,account_code,expected_line_count,actual_line_count,expected_debit,expected_credit,actual_debit,actual_credit,expected_hash,actual_hash,status,row_document,row_hash)
 SELECT new_id,p_tenant,p_entity,COALESCE(e.period_id,a.period_id),COALESCE(e.period_code,a.period_code),COALESCE(e.currency,a.currency),'PAYABLE',COALESCE(e.account_code,a.account_code),COALESCE(e.line_count,0),COALESCE(a.line_count,0),COALESCE(e.debit,0),COALESCE(e.credit,0),COALESCE(a.debit,0),COALESCE(a.credit,0),e.row_hash,a.row_hash,CASE WHEN e.line_count IS NOT DISTINCT FROM a.line_count AND e.debit IS NOT DISTINCT FROM a.debit AND e.credit IS NOT DISTINCT FROM a.credit THEN 'MATCHED' ELSE 'MISMATCH' END,z.doc,refs_jsonb_hash(z.doc) FROM _wbs273_expected e FULL JOIN _wbs273_actual a USING(period_id,period_code,currency,account_code) CROSS JOIN LATERAL (SELECT jsonb_build_object('schema_version','WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION_ACCOUNT_V1','period_id',COALESCE(e.period_id,a.period_id),'period_code',COALESCE(e.period_code,a.period_code),'currency',COALESCE(e.currency,a.currency),'module_code','PAYABLE','account_code',COALESCE(e.account_code,a.account_code),'expected_line_count',COALESCE(e.line_count,0),'actual_line_count',COALESCE(a.line_count,0),'expected_debit_amount',to_char(COALESCE(e.debit,0),'FM999999999999999999990.0000'),'expected_credit_amount',to_char(COALESCE(e.credit,0),'FM999999999999999999990.0000'),'actual_debit_amount',to_char(COALESCE(a.debit,0),'FM999999999999999999990.0000'),'actual_credit_amount',to_char(COALESCE(a.credit,0),'FM999999999999999999990.0000'),'expected_hash',e.row_hash,'actual_hash',a.row_hash,'status',CASE WHEN e.line_count IS NOT DISTINCT FROM a.line_count AND e.debit IS NOT DISTINCT FROM a.debit AND e.credit IS NOT DISTINCT FROM a.credit THEN 'MATCHED' ELSE 'MISMATCH' END) AS doc) z;
 payload:=jsonb_build_object('reconciliation_id',new_id,'control_run_id',p_control_run,'receipt_hash',stored.receipt_hash,'status',result_status);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION_RETAINED','WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION',new_id,'RETAIN',actor,'USER','WBS.H1.ACCOUNTING.RECONCILE',p_idempotency_key,p_idempotency_key,p_idempotency_key,stored.receipt_hash,btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION',new_id,'WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION_RETAINED',payload,refs_jsonb_hash(payload));
 RETURN doc||jsonb_build_object('reconciliation_id',new_id,'receipt_hash',stored.receipt_hash,'idempotent',false);
END $$;

CREATE FUNCTION refs_read_wbs_h1_accounting_control_reconciliation(p_tenant uuid,p_entity uuid,p_reconciliation uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'WBS.AUTOREC.VIEW');SELECT r.receipt_document||jsonb_build_object('reconciliation_id',r.reconciliation_id,'receipt_hash',r.receipt_hash,'retained_by',r.retained_by,'retained_at',r.retained_at,'account_rows',COALESCE((SELECT jsonb_agg(a.row_document||jsonb_build_object('row_hash',a.row_hash) ORDER BY a.period_code,a.currency,a.account_code) FROM wbs_h1_accounting_control_reconciliation_account a WHERE a.reconciliation_id=r.reconciliation_id),'[]'::jsonb)) INTO result FROM wbs_h1_accounting_control_reconciliation r WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.reconciliation_id=p_reconciliation;IF result IS NULL THEN RAISE EXCEPTION 'WBS H1 accounting reconciliation not found' USING ERRCODE='P0002';END IF;RETURN result;END $$;

CREATE FUNCTION refs_list_wbs_h1_accounting_control_reconciliations(p_tenant uuid,p_entity uuid,p_control_run uuid DEFAULT NULL,p_limit integer DEFAULT 50,p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;total_count integer;BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'WBS.AUTOREC.VIEW');IF p_limit IS NULL OR p_offset IS NULL OR p_limit<1 OR p_limit>200 OR p_offset<0 THEN RAISE EXCEPTION 'WBS reconciliation pagination is invalid' USING ERRCODE='22023';END IF;SELECT count(*)::integer INTO total_count FROM wbs_h1_accounting_control_reconciliation WHERE tenant_id=p_tenant AND entity_id=p_entity AND (p_control_run IS NULL OR control_run_id=p_control_run);SELECT jsonb_build_object('schema_version','WBS_H1_ACCOUNTING_CONTROL_RECONCILIATION_LIST_V1','tenant_id',p_tenant,'entity_id',p_entity,'control_run_id',p_control_run,'limit',p_limit,'offset',p_offset,'total_count',total_count,'population_complete',true,'page_complete',p_offset+p_limit>=total_count,'cursor_next',CASE WHEN p_offset+p_limit<total_count THEN p_offset+p_limit ELSE NULL END,'rows',COALESCE(jsonb_agg(x.receipt_document||jsonb_build_object('reconciliation_id',x.reconciliation_id,'receipt_hash',x.receipt_hash,'retained_at',x.retained_at) ORDER BY x.retained_at DESC,x.reconciliation_id DESC),'[]'::jsonb),'can_create_draft',false,'can_review',false,'can_approve',false,'can_post',false) INTO result FROM (SELECT * FROM wbs_h1_accounting_control_reconciliation WHERE tenant_id=p_tenant AND entity_id=p_entity AND (p_control_run IS NULL OR control_run_id=p_control_run) ORDER BY retained_at DESC,reconciliation_id DESC LIMIT p_limit OFFSET p_offset) x;RETURN result;END $$;

REVOKE EXECUTE ON FUNCTION refs_retain_wbs_h1_accounting_control_reconciliation(uuid,uuid,uuid,text,text,text,text,text),refs_read_wbs_h1_accounting_control_reconciliation(uuid,uuid,uuid),refs_list_wbs_h1_accounting_control_reconciliations(uuid,uuid,uuid,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_retain_wbs_h1_accounting_control_reconciliation(uuid,uuid,uuid,text,text,text,text,text),refs_read_wbs_h1_accounting_control_reconciliation(uuid,uuid,uuid),refs_list_wbs_h1_accounting_control_reconciliations(uuid,uuid,uuid,integer,integer) TO refs_app;

COMMIT;
